WITH src AS (SELECT * FROM web_events WHERE session_id IN (11, 26, 27, 39)), EventMonthSummary AS (SELECT DATE_FORMAT(event_time, 'yyyy-MM') AS event_month, SUM(CASE WHEN event_type = 'search' THEN duration_sec ELSE 0 END) AS search_duration_sec, ROUND((100 * SUM(CASE WHEN event_type = 'search' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_search FROM src GROUP BY DATE_FORMAT(event_time, 'yyyy-MM')) SELECT event_month, search_duration_sec FROM EventMonthSummary WHERE pct_search < 27 ORDER BY 2 DESC
